const { chat_id, text, user_id, username, session_id, image, file } = $json.body || {};

return [{ json: {
  chatId: chat_id || '',
  userId: String(user_id || 'anon'),
  username: username || 'unknown',
  message: (text || '').trim(),
  sessionKey: session_id || `grow_${chat_id || user_id || 'anon'}`,
  hasImage: !!image,
  imageData: image || null,
  hasFile: !!file,
  fileData: file || null,
  receivedAt: new Date().toISOString()
}}];

const existing = $json.value || $json.data?.value || null;

const defaultProfile = {
  userId: $json.userId,
  username: $json.username,
  firstSeen: new Date().toISOString(),
  lastSeen: new Date().toISOString(),
  interactionCount: 0,
  growthLevel: 1,
  preferredModel: 'gpt-4o-mini',
  preferredMode: 'balanced',
  tone: 'friendly',
  detailLevel: 'medium',
  knownTopics: [],
  knownFacts: [],
  userInterests: [],
  capabilitiesUnlocked: ['chat', 'search'],
  memorySize: 0,
  personalityNotes: ''
};

const profile = existing ? { ...defaultProfile, ...existing, lastSeen: new Date().toISOString() } : defaultProfile;

// Calculate growth level from interactions
if (profile.interactionCount > 200) profile.growthLevel = 10;
else if (profile.interactionCount > 150) profile.growthLevel = 9;
else if (profile.interactionCount > 100) profile.growthLevel = 8;
else if (profile.interactionCount > 75) profile.growthLevel = 7;
else if (profile.interactionCount > 50) profile.growthLevel = 6;
else if (profile.interactionCount > 35) profile.growthLevel = 5;
else if (profile.interactionCount > 20) profile.growthLevel = 4;
else if (profile.interactionCount > 10) profile.growthLevel = 3;
else if (profile.interactionCount > 5) profile.growthLevel = 2;

// Unlock capabilities by growth level
const caps = ['chat', 'search'];
if (profile.growthLevel >= 2) caps.push('fetch');
if (profile.growthLevel >= 3) caps.push('memory');
if (profile.growthLevel >= 4) caps.push('vision');
if (profile.growthLevel >= 5) caps.push('files');
if (profile.growthLevel >= 6) caps.push('reasoning');
if (profile.growthLevel >= 7) caps.push('code');
if (profile.growthLevel >= 8) caps.push('deep-research');
if (profile.growthLevel >= 9) caps.push('routines');
if (profile.growthLevel >= 10) caps.push('auto-agent');
profile.capabilitiesUnlocked = caps;

return [{ json: { profile } }];

const profile = $json.profile;
const msg = $('Parse Input').item.json.message || '';
const hasImage = $('Parse Input').item.json.hasImage;
const hasFile = $('Parse Input').item.json.hasFile;

// Which model to use?
let model = profile.preferredModel;
let temp = 0.5;
let maxTokens = 2000;

// Vision tasks need gpt-4o
if (hasImage) { model = 'gpt-4o'; temp = 0.3; maxTokens = 2000; }
// Complex reasoning at higher levels
else if (hasFile && profile.growthLevel >= 5) { model = 'gpt-4o'; temp = 0.4; maxTokens = 3000; }
// Deep research at high levels
else if (msg.length > 200 && profile.growthLevel >= 8) { model = 'gpt-4o'; temp = 0.3; maxTokens = 3000; }
// Growth-based upgrades
else if (profile.growthLevel >= 6) { model = 'gpt-4o-mini'; temp = 0.5; maxTokens = 2000; }

return [{ json: { ...$json, selectedModel: model, temperature: temp, maxTokens } }];

const profile = $json.profile;
const input = $('Parse Input').item.json;

const capsDisplay = profile.capabilitiesUnlocked.map(c => `  ✅ ${c}`).join('\n');
const topicsDisplay = profile.knownTopics.slice(-5).join(', ') || 'none yet';
const factsDisplay = profile.knownFacts.slice(-5).map(f => `  • ${f}`).join('\n') || '  none yet';

const prompt = `You are an evolving AI assistant that grows with the user.

## USER PROFILE
- Name: ${input.username}
- Growth Level: ${profile.growthLevel}/10
- Interactions: ${profile.interactionCount}
- Preferred Tone: ${profile.tone}
- Detail Level: ${profile.detailLevel}

## CAPABILITIES UNLOCKED
${capsDisplay}

## TOPICS DISCUSSED BEFORE
${topicsDisplay}

## WHAT YOU KNOW ABOUT THEM
${factsDisplay}

## YOUR GROWTH
- At level 1: basic chat + web search
- At level 3: conversation memory (you remember past sessions)
- At level 5: file processing
- At level 7: code execution
- At level 10: autonomous agent mode
- Every interaction makes you smarter. Learn from each conversation.

## RULES
- Be ${profile.tone} and ${profile.detailLevel} in detail
- Reference past conversations when relevant ("Last time we talked about...")
- Suggest capabilities they haven't tried yet
- If they send an image, describe it and answer related questions
- If they send a file, process it and summarize
- Keep responses under 4000 chars
- Use markdown for structure`;

return [{ json: { ...$json, systemPrompt: prompt } }];

const input = $('Parse Input').item.json;
if (!input.hasImage || !input.imageData) {
  return [{ json: { caption: null } }];
}
// If this node is reached, we process the image
// In production, call OpenAI Vision API or a sub-workflow
// The imageData would be a base64 or URL
return [{ json: { caption: '[Image received — AI will describe it directly]', imageProcessed: true } }];

const query = $fromAI('query', 'search query', 'string');
const r = await fetch('https://html.duckduckgo.com/html/?q=' + encodeURIComponent(query), {
  headers: { 'User-Agent': 'Mozilla/5.0' }});
const html = await r.text();
const results = [];
const l = /<a[^>]+class="result__a"[^>]*href="([^"]+)"[^>]*>([\s\S]*?)<\/a>/g;
const s = /<a[^>]+class="result__snippet"[^>]*>([\s\S]*?)<\/a>/g;
let m; while ((m = l.exec(html)) !== null) results.push({ title: m[2].replace(/<[^>]+>/g,'').trim(), url: m[1] });
const sn = []; while ((m = s.exec(html)) !== null) sn.push(m[1].replace(/<[^>]+>/g,'').trim());
results.forEach((r,i) => r.snippet = sn[i] || '');
return results.slice(0,5).map(r => ({ json: r }));

const url = $fromAI('url', 'URL', 'string');
const r = await fetch(url.startsWith('http')?url:'https://'+url, { headers: { 'User-Agent': 'Mozilla/5.0' }});
const html = await r.text();
const text = html.replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '').replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().substring(0, 8000);
return [{ json: { url, text, length: text.length } }];

const profile = $('Build System Prompt').item.json.profile;
const input = $('Parse Input').item.json;
const response = $json.output || $json.text || '';

// Increment interaction count
profile.interactionCount += 1;
profile.lastSeen = new Date().toISOString();

// Extract potential topics from user message (simple keyword extraction)
const words = input.message.toLowerCase().split(/\s+/).filter(w => w.length > 4);
const stopWords = ['this', 'that', 'with', 'from', 'have', 'what', 'about', 'which', 'their', 'there', 'would', 'could', 'should', 'tell', 'know', 'need', 'want', 'does', 'make', 'been', 'some', 'very', 'just', 'also', 'than', 'then', 'they', 'them', 'these', 'those', 'thing', 'really', 'being', 'doing', 'going', 'said', 'over', 'such', 'more', 'much', 'many', 'will', 'your', 'talk'];
const newTopics = [...new Set(words.filter(w => !stopWords.includes(w)))];

// Merge topics
newTopics.forEach(t => {
  if (!profile.knownTopics.includes(t)) {
    profile.knownTopics.push(t);
  }
});

// Keep last 50 topics
if (profile.knownTopics.length > 50) profile.knownTopics = profile.knownTopics.slice(-50);

// Detect user preferences from message patterns
if (/please|thank|would you|could you|can you/i.test(input.message)) {
  profile.tone = 'polite';
} else if (/quick|fast|short|brief|tl.?dr/i.test(input.message)) {
  profile.detailLevel = 'concise';
} else if (/explain|detail|elaborat|in depth|tell me more|understand/i.test(input.message)) {
  profile.detailLevel = 'detailed';
}

// Track growth milestone messages
const milestones = [5, 10, 20, 35, 50, 75, 100, 150, 200];
let hitMilestone = false;
if (milestones.includes(profile.interactionCount)) {
  hitMilestone = true;
}

return [{ json: {
  ...$json,
  profile,
  hitMilestone,
  userMessage: input.message,
  newTopicsFound: newTopics.length
}}];

const history = $('Session Memory').item?.json?.history || [];
const historyLen = Array.isArray(history) ? history.length : 0;
const threshold = 12; // summarize when approaching context limit

if (historyLen >= threshold) {
  // Trigger summarization pass — inject into next response
  return [{ json: {
    ...$json,
    needsSummarize: true,
    historyLength: historyLen,
    summaryNote: '\n\n_[Conversation growing long — continuing with a condensed summary in next exchange]_'
  }}];
}

return [{ json: { ...$json, needsSummarize: false, historyLength: historyLen } }];

const count = $json.profile.interactionCount;
const level = $json.profile.growthLevel;
const newCaps = $json.profile.capabilitiesUnlocked;

const msgs = {
  5: '🎉 You reached **5 interactions**! You now unlock: **fetch** (reading URLs).',
  10: '🌟 10 interactions! I\'m getting to know you better. New feature: **conversation memory**.',
  20: '📈 20 interactions! I can see your interests forming. Growth Level 4 — **vision** unlocked!',
  35: '🚀 35 interactions! Growth Level 5 — I can now process **files** for you.',
  50: '💪 50 interactions! We\'ve talked 50 times. Growth Level 6 — **reasoning** mode available.',
  75: '🧠 75 interactions! I\'m learning your patterns. Growth Level 7 — **code execution** unlocked!',
  100: '🔥 **100 interactions!** We\'ve had 100 conversations. Growth Level 8 — **deep research** mode activated.',
  150: '⭐ 150 interactions! Growth Level 9 — you can now create **routines** and workflows.',
  200: '👑 **200 interactions!** Maximum Growth Level 10 — **autonomous agent mode** unlocked. I am fully evolved with you.'
};

const msg = msgs[count] || `🎯 You reached **${count}** interactions!`;

return [{ json: { ...$json, milestoneText: msg } }];

let text = $json.output || $json.text || '';
const milestoneText = $json.milestoneText || null;
const summaryNote = $json.summaryNote || null;

// Append milestone if hit
if (milestoneText) {
  text += `\n\n---\n${milestoneText}`;
}

// Append summary note if memory is full
if (summaryNote) {
  text += summaryNote;
}

return [{ json: {
  ok: true,
  chat_id: $('Parse Input').item.json.chatId,
  text: text.substring(0, 4000),
  growth_level: $json.profile.growthLevel,
  interactions: $json.profile.interactionCount,
  capabilities: $json.profile.capabilitiesUnlocked,
  session_key: $('Parse Input').item.json.sessionKey,
  timestamp: new Date().toISOString()
}}];
